### ARCHIVO: script.js
```js
// ===== DATOS: la ÚNICA fuente de verdad. Todo lo que se ve sale de acá. =====
/** 
 * estado: Objeto donde las claves son las coordenadas "ColFila" (ej: A1, J20) y los valores son el contenido del texto.
 */
let estado = {};

// Definición de dimensiones para inicialización
const COLS = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
const ROWS = Array.from({ length: 20 }, (_, i) => (i + 1).toString()); // De "1" a "20"

// Inicializar el estado con todas las celdas vacías
for (const col of COLS) {
    for (const row of ROWS) {
        estado[`${col}${row}`] = "";
    }
}

const CLAVE = "app";

function cargar() { 
    try { 
        const s = localStorage.getItem(CLAVE); 
        if (s) estado = JSON.parse(s); 
    } catch (e) {} 
}

function guardar() { 
    try { 
        localStorage.setItem(CLAVE, JSON.stringify(estado)); 
    } catch (e) {} 
}

// ===== LÓGICA: funciones que cambian `estado` (o calculan con él). NO tocan la página: sin document. =====

/**
 * Actualiza el estado global con el contenido de una celda específica, guardando inmediatamente.
 * @param {HTMLElement} cellElement - El elemento DOM que fue editado.
 * @param {string} value - El nuevo valor del texto.
 */
function setCellValue(cellElement, value) {
    const col = cellElement.dataset.col;
    const row = cellElement.dataset.row;
    const key = `${col}${row}`;

    if (col && row) {
        estado[key] = value;
        guardar();
        // Después de cambiar el estado, siempre debemos renderizar para reflejar los cambios.
        render(); 
    }
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const cells = document.querySelectorAll('.editable[contenteditable="true"]');

    cells.forEach(cell => {
        const col = cell.dataset.col;
        const row = cell.dataset.row;
        const key = `${col}${row}`;

        // Obtener el valor de estado o usar vacío si no existe (aunque debería existir por la inicialización)
        const value = estado[key] !== undefined ? estado[key] : "";

        // Actualizar el contenido visible del elemento DOM.
        cell.textContent = value;
    });
}

// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const cellGrid = document.getElementById('cell-grid');

    if (!cellGrid) return;

    /** 
     * Maneja el guardado de contenido cuando el usuario termina de editar (focusout). 
     * Se usa delegación de eventos en el contenedor principal (#cell-grid).
     */
    cellGrid.addEventListener('focusout', function(e) {
        if (e.target.classList.contains('editable')) {
            const target = e.target;
            // El contenido que se guarda es lo que está visible en el DOM al perder foco.
            const newValue = target.textContent; 

            setCellValue(target, newValue);
        }
    });

    /** 
     * Maneja el guardado de contenido cuando se presiona Enter (keydown).
     */
    cellGrid.addEventListener('keydown', function(e) {
        if (e.target.classList.contains('editable')) {
            // Detectar la tecla Enter
            if (e.key === 'Enter') {
                e.preventDefault(); // Prevenir el comportamiento por defecto del formulario/cursor
                const target = e.target;
                const newValue = target.textContent; 

                setCellValue(target, newValue);
            }
        }
    });
}

// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { cargar(); conectar(); render(); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
```

### FUNCION: getCellValue
```js
/**
 * Obtiene el valor numérico de una celda dada su clave "ColFila" del estado global.
 * Si la clave no existe o el valor no es un número válido, devuelve 0.
 * @param {string} key - La clave de la celda (ej: "A1").
 * @returns {number} El valor numérico o 0 si falla.
 */
function getCellValue(key) {
    const value = estado[key];
    if (value === undefined || value === null) return 0;

    // Intentar limpiar y convertir a número flotante, ignorando texto no numérico
    let cleanValue = String(value).trim();

    // Si el valor es un intento de fórmula o está vacío, lo tratamos como 0 para cálculos.
    if (cleanValue === "" || cleanValue.startsWith("=")) {
        return 0;
    }

    const num = parseFloat(cleanValue);
    return isNaN(num) ? 0 : num;
}
```

### FUNCION: calculateRangeSum
```js
/**
 * Calcula la suma de un rango de celdas (ej: A1:A3).
 * @param {string} rangeKey - La clave del rango en formato Excel (ej: "A1:A3").
 * @returns {number} La suma total.
 */
function calculateRangeSum(rangeKey) {
    const match = rangeKey.match(/([A-Z]+)([1-9]\d*):([A-Z]+)([1-9]\d*)/i);
    if (!match) return 0;

    const colStart = match[1];
    const rowStart = parseInt(match[2]);
    const colEnd = match[3];
    const rowEnd = parseInt(match[4]);

    let sum = 0;

    // Iteramos sobre las columnas y filas delimitadas por el rango.
    for (let i = rowStart; i <= rowEnd; i++) {
        const currentRow = String(i);

        // Convertir letras a índice numérico para la iteración de columnas
        const startColIndex = colStart.charCodeAt(0) - 'A'.charCodeAt(0);
        const endColIndex = colEnd.charCodeAt(0) - 'A'.charCodeAt(0);

        for (let j = startColIndex; j <= endColIndex; j++) {
            const currentColLetter = String.fromCharCode('A'.charCodeAt(0) + j);
            // Si estamos en la columna de inicio, y es diferente a la final, usamos el índice actual
            const colKey = (j === 0 && startColIndex !== endColIndex) ? currentColLetter : currentColLetter;

            if (colKey) {
                 sum += getCellValue(`${colKey}${currentRow}`);
            }
        }
    }
    return sum;
}
```

### FUNCION: evaluateFormula
```js
/**
 * Evalúa una fórmula de estilo Excel en español almacenada como string.
 * Soporta =SUMA(rango), =SUMA(c1;c2) y operaciones básicas (-, *, /).
 * @param {string} formula - La cadena que contiene la fórmula, incluyendo el signo '='.
 * @returns {number | string} El resultado numérico calculado o la fórmula original si no se pudo evaluar.
 */
function evaluateFormula(formula) {
    let cleanFormula = formula.trim();

    if (!cleanFormula || !cleanFormula.startsWith('=')) {
        return cleanFormula; // No es una fórmula
    }

    // 1. Limpiar el prefijo '='
    cleanFormula = cleanFormula.substring(1).trim();

    let result = null;

    try {
        // --- Manejo de funciones (SUMA) ---
        const sumMatch = cleanFormula.match(/SUMA\((.*)\)/i);
        if (sumMatch) {
            const argumentsList = sumMatch[1];
            let totalSum = 0;

            // Los argumentos pueden estar separados por comas o punto y coma. Usaremos `;` como separador principal si está presente.
            const args = argumentsList.split(/[;,]/).filter(a => a.trim() !== '');

            for (const arg of args) {
                let value;
                // 1. Si es un rango (A1:A3), calculamos la suma del rango
                if (arg.includes(':')) {
                    value = calculateRangeSum(arg);
                } else {
                    // 2. Es una celda suelta o referencia simple
                    value = getCellValue(arg.trim());
                }
                totalSum += value;
            }
            result = totalSum;

        } else {
             // --- Manejo de operaciones matemáticas básicas (A1-B1, A1*B1) ---

            let expression = cleanFormula.replace(/([A-Z]+[1-9]\d*)/g, (ref) => getCellValue(ref));

            if (expression.includes('+') || expression.includes('-') || expression.includes('*') || expression.includes('/')) {
                // Usamos eval con precaución ya que solo estamos reemplazando referencias de celda por números 
                // y los operadores son conocidos.
                result = Function(`return ${expression}`)(); 
            } else {
                 // Si no es una función ni operación, asumimos que el usuario quiere escribir texto o un número literal
                 const numericValue = parseFloat(cleanFormula);
                 if (!isNaN(numericValue)) {
                     result = numericValue;
                 } else {
                     return formula; // No se pudo evaluar como nada más
                 }
            }
        }

        // Si el resultado es un número finito, lo devolvemos.
        if (typeof result === 'number' && isFinite(result)) {
             return Number(Math.round(result * 100) / 100); // Redondear a dos decimales por estética
        }

    } catch (e) {
        console.error("Error evaluating formula:", e);
        // En caso de error, devolver la fórmula original para que el usuario vea su error.
        return formula;
    }

    return formula; // Fallback
}
```

