/**
 * Actualiza el estado global con el contenido de una celda específica, guardando inmediatamente.
 * Si el valor ingresado es una fórmula válida, la evalúa y guarda el resultado numérico.
 * @param {HTMLElement} cellElement - El elemento DOM que fue editado.
 * @param {string} value - El nuevo valor del texto.
 */
function setCellValue(cellElement, value) {
    const col = cellElement.dataset.col;
    const row = cellElement.dataset.row;
    const key = `${col}${row}`;
    let finalValue = value;

    if (col && row) {
        // Verificar si el valor ingresado es una fórmula
        if (value && typeof value === 'string' && value.trim().startsWith('=')) {
            finalValue = evaluateFormula(value);
        } else {
             finalValue = value; // Si no es fórmula, se guarda tal cual.
        }

        estado[key] = finalValue;
        guardar();
        render(); 
    }
}
