```js
/**
 * Intenta evaluar una fórmula de estilo Excel almacenada en el estado global.
 * Soporta SUMA(rango o lista de celdas) y operaciones aritméticas básicas (A1+B2, etc.).
 * @param {string} formulaString - La cadena de texto que comienza con '='.
 * @returns {string} El resultado calculado como string, o la fórmula original si falla el cálculo.
 */
function calculateValue(formulaString) {
    if (!formulaString || !typeof formulaString === 'string' || !formulaString.startsWith('=')) {
        return formulaString;
    }

    let expression = formulaString.substring(1).trim(); // Remove '='

    // 1. Handle SUMA() formulas (SUMA(rango) o SUMA(c1; c2; ...)).
    if (expression.toUpperCase().startsWith("SUMA")) {
        const match = expression.match(/SUMA\((.+)\)/);
        if (!match) return formulaString;

        let argumentsString = match[1].trim();
        let valuesToSum = [];

        // Check for range (e.g., A1:A3). We assume single column ranges based on typical usage/test case.
        const rangeMatch = argumentsString.match(/([A-Z]+[0-9]+):?([A-Z]+[0-9]+)/);
        if (rangeMatch) {
            let startRef = rangeMatch[1];
            let endRef = rangeMatch[2];

            // Extract column letter and row number
            const startCol = startRef.match(/[A-Z]+/)[0];
            const startRow = parseInt(startRef.replace(/[A-Z]+/g, ''));
            const endCol = endRef.match(/[A-Z]+/)[0];
            const endRow = parseInt(endRef.replace(/[A-Z]+/g, ''));

            // If the column letters are different, this function is too limited and assumes single column ranges for robustness.
            if (startCol !== endCol) {
                 return formulaString; 
            }

            let currentR = startRow;
            while (currentR <= endRow) {
                const key = `${startCol}${currentR}`;
                // Use parseFloat to handle numeric conversion, default to 0 if state value is missing or non-numeric.
                const value = parseFloat(estado[key]) || 0; 
                valuesToSum.push(value);
                currentR++;
            }
        } else {
            // List of cells (A1;B2;C3)
            const refs = argumentsString.split(';');
            for (const ref of refs) {
                const trimmedRef = ref.trim();
                if (trimmedRef) {
