    // 2. Handle basic arithmetic operations (A1-B1, A1*B2/C3).
    try {
        // Reemplaza todas las referencias de celdas (ej: A1) con su valor numérico real del estado.
        const cellRefRegex = /([A-Z]+[0-9]+)/g; 
        let tempExpression = expression.replace(cellRefRegex, (match) => {
            const value = parseFloat(estado[match]);
            return isNaN(value) ? '0' : value; // Reemplaza la referencia con el valor numérico o 0 si no existe/no es número
        });

        // Usa eval() para calcular la expresión matemática resultante.
        const result = eval(tempExpression); 
        return String(result);
    } catch (e) {
