/**
 * Evalúa una fórmula de hoja de cálculo almacenada como string en estado.
 * @param {string} formula - La cadena que comienza con '=' (ej: "=B1+C2").
 * @returns {string} El resultado calculado o un mensaje de error.
 */
function evaluateFormula(formula) {
    // 1. Eliminar el signo inicial '=' para procesar la expresión matemática pura.
    let expression = formula.startsWith('=') ? formula.substring(1) : '';
    if (!expression) return "";

    // Regex para identificar referencias de celda (ej: A1, B20). [A-Z]+ son letras, [0-9]+ son números.
    const regex = /([A-Z]+[0-9]+)/g;

    // 2. Reemplazar todas las referencias de celda con sus valores actuales del estado.
    let calculatedExpression = expression.replace(regex, (match) => {
        const value = getCellValue(match);
        // Usamos el valor numérico obtenido por getCellValue para la evaluación.
        return typeof value === 'number' ? value.toString() : '0';
    });

    try {
        // 3. Evaluar la expresión matemática resultante (eval() es necesario aquí, pero controlado).
        const result = eval(calculatedExpression);
        if (isNaN(result) || !isFinite(result)) return "Error"; // Manejar errores matemáticos
        return String(Math.round(result * 100) / 100); // Redondear a 2 decimales para consistencia
    } catch (e) {
        console.error("Formula evaluation error:", e);
        return "ERROR"; // Indicar fallo de evaluación
    }
}
