// ===== DATOS: la ÚNICA fuente de verdad. Todo lo que se ve sale de acá. =====
/** 
 * estado: Objeto donde las claves son las coordenadas "ColFila" (ej: A1, J20) y los valores son el contenido del texto.
 */
let estado = {};

// Definición de dimensiones para inicialización
const COLS = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
const ROWS = Array.from({ length: 20 }, (_, i) => (i + 1).toString()); // De "1" a "20"

// Inicializar el estado con todas las celdas vacías
for (const col of COLS) {
    for (const row of ROWS) {
        estado[`${col}${row}`] = "";
    }
}

const CLAVE = "app";

function cargar() { 
    try { 
        const s = localStorage.getItem(CLAVE); 
        if (s) estado = JSON.parse(s); 
    } catch (e) {} 
}

function guardar() { 
    try { 
        localStorage.setItem(CLAVE, JSON.stringify(estado)); 
    } catch (e) {} 
}

// ===== LÓGICA: funciones que cambian `estado` (o calculan con él). NO tocan la página: sin document. =====

/**
 * Obtiene el valor de una celda del estado global, devolviendo 0 si no existe o es nulo para cálculos.
 * @param {string} key - La clave de la celda (ej: A1).
 * @returns {number|string} El valor actual.
 */
function getCellValue(key) {
    // Si el estado no tiene la clave, asumimos que es un valor vacío para cálculos.
    return estado[key] !== undefined ? estado[key] : 0;
}

/**
 * Evalúa una fórmula matemática (ej: "=B1+C1") usando los valores actuales en 'estado'.
 * @param {string} formulaString - La cadena de texto con la fórmula.
 * @returns {number|string} El resultado calculado o un mensaje de error/texto.
 */
function evaluateFormula(formulaString) {
    if (!formulaString || !formulaString.startsWith('=')) {
        return formulaString; // No es fórmula, devuelve el valor original
    }

    // Quitar '=' inicial y normalizar espacios
    let expression = formulaString.substring(1).trim();

    // 1. Reemplazar referencias de celda (ej: A1) por sus valores numéricos reales en JS.
    // Esta regex busca patrones como letras seguidas de números (A1, B20, etc.)
    expression = expression.replace(/([A-Z]+[0-9]+)/g, (match) => {
        const value = getCellValue(match);
        if (typeof value === 'string' && !isNaN(parseFloat(value))) {
            return parseFloat(value); // Si es un número válido, lo convertimos a número JS
        } 
        // Si el valor de la celda es texto o no se encontró, lo tratamos como 0 para evitar NaN en sumas/restas.
        return value === "" ? 0 : parseFloat(value) || 0;
    });

    try {
        // Evaluar la expresión matemática resultante usando el scope del estado.
        return eval(expression);
    } catch (e) {
        console.error("Error evaluating formula:", e);
        return "ERROR"; // Devolver un mensaje de error si la fórmula falla
    }
}

/**
 * Itera sobre todas las celdas en el estado. Si contienen una fórmula, recalcula su valor basado en 
 * los valores actuales del estado y actualiza el estado global.
 */
function recalculateAllFormulas() {
    let formulasUpdated = false;
    const keysToRecalculate = [];

    // 1. Identificar todas las celdas que contienen fórmulas en el estado actual.
    for (const key in estado) {
        const value = estado[key];
        if (typeof value === 'string' && value.startsWith('=')) {
            keysToRecalculate.push(key);
        }
    }

    // 2. Recalcular y actualizar el estado de cada fórmula detectada.
    for (const key of keysToRecalculate) {
        const formulaInput = estado[key];
        const newValue = evaluateFormula(formulaInput);

        // Solo actualizamos si el valor calculado es diferente al valor almacenado.
        if (String(newValue) !== String(estado[key])) {
            // Actualizar el estado con el resultado numérico/string y luego forzar un render.
            estado[key] = String(newValue); 
            formulasUpdated = true;
        }
    }

    if (formulasUpdated) {
        // Después de calcular todos los valores, renderizar toda la cuadrícula para mostrar los resultados.
        render();
        guardar(); // Guardamos el nuevo estado calculado
    }
}


/**
 * Actualiza el estado global con el contenido de una celda específica, guardando inmediatamente.
 * Si detecta un signo '=', calcula el resultado y actualiza el estado recursivamente llamando a recalculateAllFormulas().
 * @param {HTMLElement} cellElement - El elemento DOM que fue editado.
 * @param {string} value - El nuevo valor del texto (puede ser la fórmula o el resultado).
 */
function setCellValue(cellElement, value) {
    const col = cellElement.dataset.col;
    const row = cellElement.dataset.row;
    const key = `${col}${row}`;

    if (col && row) {
        let processedValue = String(value).trim();
        let finalStateValue;

        // 1. Determinar si es una fórmula y procesarla.
        if (processedValue.startsWith('=')) {
            const calculatedResult = evaluateFormula(processedValue);
            finalStateValue = String(calculatedResult);
        } else {
            finalStateValue = processedValue;
        }

        // 2. Actualizar el estado global con el valor final (calculado o ingresado).
        estado[key] = finalStateValue;
        guardar();

        // 3. Limpiar la celda visible para reflejar el resultado calculado en el DOM
        cellElement.textContent = finalStateValue;

        // 4. NOTIFICAR: Dado que un valor base cambió, debemos recalcular todas las fórmulas dependientes.
        recalculateAllFormulas();
    }
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const cells = document.querySelectorAll('.editable[contenteditable="true"]');

    cells.forEach(cell => {
        const col = cell.dataset.col;
        const row = cell.dataset.row;
        const key = `${col}${row}`;

        // Obtener el valor de estado o usar vacío si no existe (aunque debería existir por la inicialización)
        const value = estado[key] !== undefined ? estado[key] : "";

        // Actualizar el contenido visible del elemento DOM.
        cell.textContent = value;
    });
}

// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const cellGrid = document.getElementById('cell-grid');

    if (!cellGrid) return;

    /** 
     * Maneja el guardado de contenido cuando el usuario termina de editar (focusout). 
     * Se usa delegación de eventos en el contenedor principal (#cell-grid).
     */
    cellGrid.addEventListener('focusout', function(e) {
        if (e.target.classList.contains('editable')) {
            const target = e.target;
            // El contenido que se guarda es lo que está visible en el DOM al perder foco.
            const newValue = target.textContent; 

            setCellValue(target, newValue);
        }
    });

    /** 
     * Maneja el guardado de contenido cuando se presiona Enter (keydown).
     */
    cellGrid.addEventListener('keydown', function(e) {
        if (e.target.classList.contains('editable')) {
            // Detectar la tecla Enter
            if (e.key === 'Enter') {
                e.preventDefault(); // Prevenir el comportamiento por defecto del formulario/cursor
                const target = e.target;
                const newValue = target.textContent; 

                setCellValue(target, newValue);
            }
        }
    });
}

// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { cargar(); conectar(); render(); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
