 * @param {string} key - La clave de la celda en formato "ColFila" (ej: A1).
 * @returns {number|string} El valor numérico calculado o el texto original.
 */
function getCellValue(key) {
    let value = estado[key] || "";

    // Si no es una cadena que empieza por '=', asumimos que es un valor estático o vacío.
    if (!value.startsWith('=')) {
        return value;
    }

    try {
        const formula = value.substring(1); // Quitar el '='
        let expression = formula;

        // Regex para encontrar referencias de celda (ej: A1, B20)
        // Captura letras seguidas por números (Col + Row)
        const cellRegex = /([A-Z]+[0-9]+)/g;

        // Reemplazar todas las referencias de celda con sus valores actuales.
        expression = expression.replace(cellRegex, (match) => {
            return getCellValue(match); // Llamada recursiva para resolver dependencias
        });

        // Evaluar la expresión matemática resultante.
        // Se usa parseFloat o parseInt para asegurar que el resultado sea numérico si es posible.
        const result = eval(expression);

        if (isNaN(result) || !isFinite(result)) {
            return "Error"; // Manejo simple de errores de fórmula
        }

        // Devolvemos el valor calculado, formateado como string para consistencia con estado.
        return String(parseFloat(result).toFixed(2)); 

