                const target = e.target;
                const newValue = target.textContent; 

                setCellValue(target, newValue);
            }
        }
    });

    // 2. Conexión de Color (Nuevo)
    if (colorControlContainer && colorControlContainer.querySelector('#colorPicker')) {
        const colorInput = document.getElementById('colorPicker');
        const applyButton = document.getElementById('applyColorBtn');

        // Escuchar el cambio en el input del color
        colorInput.addEventListener('input', () => {
            if (colorInput.value) {
                applyButton.disabled = false;
            } else {
                applyButton.disabled = true;
            }
        });

        // Aplicar el color al hacer clic en el botón
        applyButton.addEventListener('click', () => {
            const targetCell = document.querySelector('.selected-cell'); // Asumimos que hay una clase o mecanismo para saber qué celda está seleccionada/activa
            const selectedColor = colorInput.value;

            if (targetCell && selectedColor) {
                setCellColor(targetCell, selectedColor);
            }
        });
    }
}
