```js
function deleteSelectedColumn() {
    if (!selectedColumn) return;

    const colToDelete = selectedColumn;
    const rows = Array.from({ length: 20 }, (_, i) => (i + 1).toString()); // De "1" a "20"

    // 1. Actualizar el estado global, borrando todas las claves de esa columna
    for (const row of rows) {
        delete estado[`${colToDelete}${row}`];
    }

    // 2. Restructurar DOM: eliminar todos los elementos de la columna seleccionada
    let cellsToRemove = document.querySelectorAll(`.cell[data-col="${colToDelete}"]`);
    cellsToRemove.forEach(cell => cell.remove());

    // 3. Reajustar el encabezado (column letters y controls)
    const colLettersContainer = document.querySelector('.col-labels');
    let letterToRemove = document.querySelector(`.col-letter[data-col="${colToDelete}"]`);
    if (letterToRemove) {
        letterToRemove.remove();
    }

    // 4. Reajustar la grilla de celdas para que el espacio quede vacío (simulando compresión)
    const cellGrid = document.getElementById('cell-grid');
    const allCells = Array.from(document.querySelectorAll('.cell'));

    // Filtramos y reinsertamos las celdas, saltándonos la columna eliminada
    let newCellHtml = '';
    let currentColIndex = 0; // Índice de columna física (A=0, B=1...)

    allCells.forEach(cell => {
        const cellCol = cell.dataset.col;
        // Si el índice actual no coincide con la columna a eliminar, lo mantenemos.
        if (cellCol !== colToDelete) {
            newCellHtml += cell.outerHTML;
            currentColIndex++;
        }
    });

    // Limpiar y rellenar el contenido de #cell-grid
    document.getElementById('cell-grid').innerHTML = '';
    // Nota: Esto es extremadamente rudimentario, pero cumple con la mínima modificación necesaria para hacer que "desaparezca" la columna en el DOM sin recrear toda la grilla.
    document.getElementById('cell-grid').innerHTML = newCellHtml;


    // 5. Limpiar estado interno y UI
    selectedColumn = null;
    guardar();
    render(); // Renderizar para reflejar los cambios de datos (aunque no habrá cambios visibles en el contenido, sí se asegura que la grilla esté limpia)
}
