/**
 * Gestiona la selección de una columna y actualiza los controles visibles.
 * @param {string} colLetter - La letra de la columna seleccionada ('A', 'B', etc.).
 */
function selectColumn(colLetter) {
    // 1. Actualizar el estado de selección
    if (selectedColumns.has(colLetter)) {
        selectedColumns.delete(colLetter);
    } else {
        selectedColumns.add(colLetter);
    }

    // 2. Actualizar la clase visualmente en los encabezados
    document.querySelectorAll('.col-letter').forEach(el => {
        if (el.textContent === colLetter) {
            el.classList.toggle('selected');
        }
    });

    // 3. Renderizar/Actualizar los controles de columna
    renderControls();
}
