### FUNCION: deleteColumn
```js
/**
 * Elimina una columna seleccionada (si hay al menos una).
 */
function deleteColumn() {
    if (selectedColumns.size === 0) return;

    const colsToDelete = Array.from(selectedColumns);

    // Deshabilitar la edición en las celdas y eliminar los elementos DOM
    colsToDelete.forEach(col => {
        for (let r = 1; r <= 20; r++) {
            const key = `${col}${r}`;
            if (estado[key] !== undefined) {
                delete estado[key]; // Limpiar el estado primero
            }
        }
    });

    // Eliminar las etiquetas de columna y las celdas correspondientes del DOM
    colsToDelete.forEach(col => {
        const colLetters = document.querySelectorAll(`.col-letter:contains("${col}")`);
        colLetters.forEach(el => el.remove()); // Remove column letter header

        // Asume que la estructura de celdas sigue un patrón regular (A1, B1...)
        for (let r = 1; r <= 20; r++) {
            const selector = `.editable[data-col="${col}"][data-row="${r}"]`;
            const cellElement = document.querySelector(selector);
            if (cellElement) {
                // Eliminar la celda del DOM y borrar su estado de datos si lo hubiera
                cellElement.remove();
            }
        }
    });

    // Limpiar el estado visual y los controles
    selectedColumns.clear();
    renderControls();
    guardar(); // Guardar después de la modificación estructural masiva
    render();
}
