### FUNCION: setColumnColor
```js
/**
 * Cambia el fondo de todas las celdas de una columna seleccionada al color especificado.
 * @param {string} hexColor - El color hexadecimal (ej: #ffffcc).
 */
function setColumnColor(hexColor) {
    if (selectedColumns.size === 0 || !hexColor) return;

    const cols = Array.from(selectedColumns);

    cols.forEach(col => {
        for (let r = 1; r <= 20; r++) {
            // Seleccionar la celda específica en el DOM
            const selector = `.editable[data-col="${col}"][data-row="${r}"]`;
            const cellElement = document.querySelector(selector);

            if (cellElement) {
                // Aplicar el fondo directamente al elemento de la celda
                cellElement.style.backgroundColor = hexColor;
            }
        }
    });
    guardar(); // Guardar, aunque no se cambian datos, es buena práctica después de una acción de control.
}
