function conectar() {
    const cellGrid = document.getElementById('cell-grid');
    const colLettersContainer = document.querySelector('.col-labels');
    const btnClear = document.getElementById('btn-clear-col');
    const btnColor = document.getElementById('btn-color-col');
    const btnDelete = document.getElementById('btn-delete-col');

    if (!cellGrid || !colLettersContainer) return;

    // 1. Listener para seleccionar columna haciendo clic en la letra (A, B, C...)
    colLettersContainer.addEventListener('click', function(e) {
        const target = e.target.closest('.col-letter');
        if (target && !target.classList.contains('selected')) {
            selectColumn(target.dataset.col);
        }
    });

    // 2. Listener de delegación para guardar contenido al perder foco o Enter en cualquier celda editable
    cellGrid.addEventListener('focusout', function(e) {
        if (e.target.classList.contains('editable')) {
            const target = e.target;
            const newValue = target.textContent; 
            setCellValue(target, newValue);
        }
    });

    cellGrid.addEventListener('keydown', function(e) {
        if (e.target.classList.contains('editable')) {
            if (e.key === 'Enter') {
                e.preventDefault();
                const target = e.target;
                const newValue = target.textContent; 

                setCellValue(target, newValue);
            }
        }
    });


    // 3. Listeners para los nuevos controles de columna
    btnClear.addEventListener('click', () => {
        if (selectedColumn) {
            clearColumnContent(selectedColumn);
        }
    });

    btnColor.addEventListener('click', () => {
        if (selectedColumn) {
            // Usar un color llamativo por defecto, o permitir selección de color si fuera más complejo.
            const defaultColor = '#ffebcc'; // Amarillo claro
            changeColumnColor(selectedColumn, defaultColor);
        }
    });

    btnDelete.addEventListener('click', () => {
        if (selectedColumn) {
            deleteColumn(selectedColumn);
        }
    });
}
