 * @param {string} colLetter - La letra de la columna ('A', 'B', etc.).
 */
function deleteColumn(colLetter) {
    if (!confirm(`¿Estás seguro de que deseas borrar toda la Columna ${colLetter}? Esta acción no se puede deshacer.`)) {
        return;
    }

    // 1. Limpiar el estado para todas las celdas de esta columna
    for (const row of ROWS) {
        delete estado[`${colLetter}${row}`];
    }

    // 2. Eliminar la estructura DOM de la columna:
    const cellsToRemove = document.querySelectorAll(`.editable[data-col="${colLetter}"]`);
    cellsToRemove.forEach(cell => cell.remove());

    // 3. Remover el elemento span de la letra del encabezado
    const colLabelElement = document.querySelector(`.col-letter[data-col="${colLetter}"]`);
    if (colLabelElement) {
        colLabelElement.remove();
    }

    guardar();
    render(); // Redibujar para reflejar el cambio de estructura

    // 4. Resetear la selección y controles
    selectedColumn = null;
    document.querySelectorAll('.col-letter').forEach(el => el.style.backgroundColor = '');
    updateControlButtons(false);
}
