```javascript
// ===== DATOS: la ÚNICA fuente de verdad. Todo lo que se ve sale de acá. =====
/** 
 * estado: Objeto donde las claves son las coordenadas "ColFila" (ej: A1, J20) y los valores son el contenido del texto.
 */
let estado = {};
// Variable para rastrear la columna actualmente seleccionada por el usuario.
let selectedColumn = null;

// Definición de dimensiones para inicialización
const COLS = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
const ROWS = Array.from({ length: 20 }, (_, i) => (i + 1).toString()); // De "1" a "20"

// Inicializar el estado con todas las celdas vacías
for (const col of COLS) {
    for (const row of ROWS) {
        estado[`${col}${row}`] = "";
    }
}

const CLAVE = "app";

function cargar() { 
    try { 
        const s = localStorage.getItem(CLAVE); 
        if (s) estado = JSON.parse(s); 
    } catch (e) {} 
}

function guardar() { 
    try { 
        localStorage.setItem(CLAVE, JSON.stringify(estado)); 
    } catch (e) {} 
}

// ===== LÓGICA: funciones que cambian `estado` (o calculan con él). NO tocan la página: sin document. =====

/**
 * Actualiza el estado global con el contenido de una celda específica, guardando inmediatamente.
 * @param {HTMLElement} cellElement - El elemento DOM que fue editado.
 * @param {string} value - El nuevo valor del texto.
 */
function setCellValue(cellElement, value) {
    const col = cellElement.dataset.col;
    const row = cellElement.dataset.row;
    const key = `${col}${row}`;

    if (col && row) {
        estado[key] = value;
        guardar();
        // Después de cambiar el estado, siempre debemos renderizar para reflejar los cambios.
        render(); 
    }
}

/**
 * Selecciona una columna, actualiza el estado y habilita controles.
 * @param {string} colId - La letra de la columna seleccionada (ej: 'A').
 */
function selectColumn(colId) {
    // Deseleccionar cualquier columna previamente activa
    if (selectedColumn) {
        document.querySelectorAll('.col-letter').forEach(el => el.classList.remove('selected'));
        document.getElementById('column-controls').disabled = true;
    }

    selectedColumn = colId;

    // Seleccionar la nueva columna visualmente
    const targetLetter = document.querySelector(`.col-letter[data-col="${colId}"]`);
    if (targetLetter) {
        targetLetter.classList.add('selected');
    }

    // Habilitar controles y limpiar colores anteriores
    document.getElementById('column-controls').disabled = false;
    document.getElementById('btn-color').disabled = false;
    document.getElementById('btn-clear').disabled = false;
    document.getElementById('btn-delete').disabled = false;

    // Opcional: Resaltar las celdas de la columna seleccionada si fuera necesario, 
    // pero por simplicidad nos enfocamos en los controles visibles.
}


/**
 * Vacía el contenido de todas las celdas en una columna dada y guarda el estado.
 * @param {string} colId - La letra de la columna a vaciar.
 */
function clearColumnContents(colId) {
    if (!selectedColumn || selectedColumn !== colId) return;

    for (const row of ROWS) {
        const key = `${colId}${row}`;
        estado[key] = ""; // Limpiar estado
    }
    guardar();
    render(); // Redibujar para reflejar el vacío
}


/**
 * Elimina completamente una columna de la hoja, limpiando el estado.
 * Nota: Para un simulador real se requeriría reconstruir toda la grilla. 
 * Aquí solo limpiamos los datos y actualizamos el estado/renderizado visualmente.
 * @param {string} colId - La letra de la columna a borrar.
 */
function deleteColumn(colId) {
    if (!selectedColumn || selectedColumn !== colId) return;

    // 1. Limpiar todos los datos asociados a esta columna en el estado
    for (const row of ROWS) {
        const key = `${colId}${row}`;
        delete estado[key];
    }

    guardar();
    render(); // Redibujar para eliminar contenido visible

    // 2. Deseleccionar y resetear controles (simplificación del manejo de DOM en este scope)
    selectedColumn = null;
    document.querySelectorAll('.col-letter').forEach(el => el.classList.remove('selected'));
    document.getElementById('column-controls').disabled = true;
}


/**
 * Aplica un color de fondo a todas las celdas de una columna dada y guarda el estado (aunque no se guarda el color en 'estado', solo lo visualmente).
 * @param {string} colId - La letra de la columna.
 * @param {string} color - El valor hexadecimal del color.
 */
function applyColorToColumn(colId, color) {
    if (!selectedColumn || selectedColumn !== colId) return;

    const cells = document.querySelectorAll(`.editable[data-col="${colId}"]`);
    cells.forEach(cell => {
        cell.style.backgroundColor = color;
    });
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const cells = document.querySelectorAll('.editable[contenteditable="true"]');

    cells.forEach(cell => {
        const col = cell.dataset.col;
        const row = cell.dataset.row;
        const key = `${col}${row}`;

        // Obtener el valor de estado o usar vacío si no existe (aunque debería existir por la inicialización)
        const value = estado[key] !== undefined ? estado[key] : "";

        // Actualizar el contenido visible del elemento DOM.
        cell.textContent = value;
    });
}

// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const cellGrid = document.getElementById('cell-grid');
    const colLabelsContainer = document.querySelector('.col-labels');
    const btnColor = document.getElementById('btn-color');
    const colorPicker = document.getElementById('color-picker');
    const btnClear = document.getElementById('btn-clear');
    const btnDelete = document.getElementById('btn-delete');

    if (!cellGrid || !colLabelsContainer) return;

    // --- Listener para selección de columna (Clic en la letra) ---
    colLabelsContainer.addEventListener('click', function(e) {
        const target = e.target.closest('.col-letter');
        if (target && target.dataset.col) {
            selectColumn(target.dataset.col);
        }
    });

    // --- Listeners de Controles ---

    // 1. Botón Color
    btnColor.addEventListener('click', () => {
        colorPicker.style.display = 'inline-block';
        colorPicker.focus();
    });
    colorPicker.addEventListener('input', (e) => {
        if (selectedColumn) {
            applyColorToColumn(selectedColumn, e.target.value);
        }
    });

    // 2. Botón Vaciar Columna
    btnClear.addEventListener('click', () => {
        if (selectedColumn) {
            clearColumnContents(selectedColumn);
        }
    });

    // 3. Botón Borrar Columna
    btnDelete.addEventListener('click', () => {
        if (selectedColumn) {
            deleteColumn(selectedColumn);
        }
    });


    /** 
     * Maneja el guardado de contenido cuando el usuario termina de editar (focusout). 
     */
    cellGrid.addEventListener('focusout', function(e) {
        if (e.target.classList.contains('editable')) {
            const target = e.target;
            // El contenido que se guarda es lo que está visible en el DOM al perder foco.
            const newValue = target.textContent; 

            setCellValue(target, newValue);
        }
    });

    /** 
     * Maneja el guardado de contenido cuando se presiona Enter (keydown).
     */
    cellGrid.addEventListener('keydown', function(e) {
        if (e.target.classList.contains('editable')) {
            // Detectar la tecla Enter
            if (e.key === 'Enter') {
                e.preventDefault(); // Prevenir el comportamiento por defecto del formulario/cursor
                const target = e.target;
                const newValue = target.textContent; 

                setCellValue(target, newValue);
            }
        }
    });
}

// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { cargar(); conectar(); render(); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
