### styles.css
```css
/* Global Reset and Body Styling */
body {
    font-family: Arial, sans-serif;
    margin: 20px;
    background-color: #f4f4f9;
}

/* Main Spreadsheet Container - Uses CSS Grid for overall structure */
#spreadsheet {
    display: grid;
    /* Define the grid layout: 1 column for row labels + 10 columns for A-J */
    grid-template-columns: 50px repeat(10, 1fr); /* Column widths (Row Label | A | B | ... | J) */
    /* Define rows: Header Row (Col Labels) + 1 header row (Row Labels) + 20 data rows = 22 total rows. Adjusting grid definition for correct spacing */
    grid-template-rows: 30px repeat(21, 50px); /* Row heights (Header | R1 | R2 | ... | R20). Total of 22 visible areas if we count the header row label area as part of the grid flow. */
    width: fit-content; /* Ensures the container is wide enough for all columns */
    border: 1px solid #ccc;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
}

/* General Header Styling (Top Labels and Corner) */
.header {
    background-color: #e0e0e0;
    border-right: 1px solid #ccc;
    border-bottom: 1px solid #ccc;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    color: #333;
}

/* Styling for the top row labels (A, B, C...) */
.col-labels {
    grid-column: 2 / span 10; /* Occupies columns 2 through 11 */
    display: flex;
    height: 30px;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    color: #333;
}

/* Specific styling for the corner placeholder (A1 intersection) */
.header.row-label {
    grid-area: 2 / 1 / 3 / 2; /* Positioned at Row 2, Column 1 (shifted down one row due to column labels moving up) */
    background-color: #d0d0d0;
    border-right: none;
    border-bottom: none;
}

/* Styling for individual column letters (A, B, C...) inside .col-labels */
.col-letter {
    flex: 1; /* Distributes space evenly among the 10 columns */
    text-align: center;
    padding: 0 5px;
}

/* Styling for Row Labels (1, 2, 3...) and Corner Cell in #cell-grid*/
.row-label {
    background-color: #e0e0e0;
    border-right: 1px solid #ccc;
    border-bottom: 1px solid #ccc;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    color: #333;
    /* These elements must occupy the first column track */
}

/* Styling for all individual data cells */
.cell {
    border-right: 1px solid #ccc;
    border-bottom: 1px solid #ccc;
    padding: 5px;
    height: 100%; /* Ensure cell fills its grid row height */
    background-color: white;
    box-sizing: border-box; /* Include padding/border in the element's total width/height */
}

/* Making cells editable and providing visual feedback */
.cell[contenteditable="true"]:focus {
    outline: 2px solid #007bff; /* Blue focus ring for user experience */
    background-color: #fffbe6; /* Light yellow background when active */
    cursor: text;
}

/* Ensure the initial content (if any) is visible and handles spacing */
.cell p, .cell span {
    margin: 0;
    padding: 0;
}
