### FUNCION: selectRow
```javascript
function selectRow(row) {
    // 1. Actualizar estado de selección global (solo se maneja la fila por ahora, asumimos que es única)
    selectedRow = row;

    // 2. Resetear resaltados en todos los elementos para limpiar el foco anterior
    document.querySelectorAll('.editable').forEach(cell => {
        cell.style.backgroundColor = ''; // Limpiar color de fondo
        cell.classList.remove('selected-row');
    });

    // 3. Aplicar resaltado a todas las celdas de la fila seleccionada (Visual Feedback)
    const cellsInRow = document.querySelectorAll(`.editable[data-row="${row}"]`);
    cellsInRow.forEach(cell => {
        cell.classList.add('selected-row');
    });

    // 4. Actualizar visibilidad y estado de los controles de fila
    const controlsEnabled = true; // Siempre habilitados al seleccionar una fila válida
    document.getElementById('btn-color-row').disabled = !controlsEnabled;
    document.getElementById('btn-clear-row').disabled = !controlsEnabled;
    document.getElementById('btn-delete-row').disabled = !controlsEnabled;

    // 5. Actualizar la visibilidad del selector de color (usamos el picker global)
    const colorPickerRow = document.getElementById('color-picker');
    if (selectedColumn !== null) { // Si hay columna seleccionada, mostrar ambos pickers para consistencia
        colorPickerRow.style.display = 'inline-block';
    } else {
        // No se requiere lógica de column selection aquí. Solo gestionamos row.
    }
}
