function deleteRowContent() {
    if (!selectedRow) return;

    const cells = document.querySelectorAll(`.editable[data-row="${selectedRow}"]`);
    let changed = false;

    cells.forEach(cell => {
        // 1. Limpiar contenido visible y estado
        cell.textContent = "";
        const key = `${cell.dataset.col}${selectedRow}`;
        if (estado[key] !== "") {
            delete estado[key];
            changed = true;
        }
    });

    // 2. Guardar el cambio de estado y redibujar para asegurar consistencia
    guardar();
    render();
}
