### FUNCION: connectListeners
```javascript
function connectListeners() {
    const cellGrid = document.getElementById('cell-grid');
    const colLabelsContainer = document.querySelector('.col-labels');
    const rowLabelsContainer = document.querySelector('.row-labels'); // Nuevo contenedor para números de fila

    // Controles de Columna
    const btnColorCol = document.getElementById('btn-color');
    const colorPickerCol = document.getElementById('color-picker-col');
    const btnClearCol = document.getElementById('btn-clear');
    const btnDeleteCol = document.getElementById('btn-delete');

    // Controles de Fila (Nuevos)
    const btnColorRow = document.getElementById('btn-color-row');
    const colorPickerRow = document.getElementById('color-picker'); // Reutiliza el input type="color"
    const btnClearRow = document.getElementById('btn-clear-row');
    const btnDeleteRow = document.getElementById('btn-delete-row');


    if (!cellGrid || !colLabelsContainer || !rowLabelsContainer) return;

    // --- Listener para selección de columna (Clic en la letra) ---
    colLabelsContainer.addEventListener('click', function(e) {
        const target = e.target.closest('.col-letter');
        if (target && target.dataset.col) {
            selectColumn(target.dataset.col);
        }
    });

    // --- Listener para selección de fila (Clic en el número) ---
    rowLabelsContainer.addEventListener('click', function(e) {
        const target = e.target.closest('.row-label');
        if (target && target.dataset.row) {
            selectRow(target.dataset.row);
        }
    });

    // --- Listeners de Controles de Columna ---

    // 1. Botón Color (Columna)
    btnColorCol.addEventListener('click', () => {
        colorPickerCol.style.display = 'inline-block';
        colorPickerCol.focus();
    });
    colorPickerCol.addEventListener('input', (e) => {
        if (selectedColumn) {
            applyColorToColumn(selectedColumn, e.target.value);
        }
    });

    // 2. Botón Vaciar Columna
    btnClearCol.addEventListener('click', () => {
        if (selectedColumn) {
            clearColumnContents(selectedColumn);
        }
    });

    // 3. Botón Borrar Columna
    btnDeleteCol.addEventListener('click', () => {
        if (selectedColumn) {
            deleteColumn(selectedColumn);
        }
    });


    // --- Listeners de Controles de Fila (Nuevos) ---

    // 1. Botón Color (Fila) - Usa el color picker reutilizado en id="color-picker"
    btnColorRow.addEventListener('click', () => {
        colorPickerRow.style.display = 'inline-block';
        colorPickerRow.focus();
    });
    colorPickerRow.addEventListener('input', (e) => {
        if (selectedRow) {
            applyColorToRow(selectedRow, e.target.value);
        }
    });

    // 2. Botón Vaciar Fila
    btnClearRow.addEventListener('click', () => {
        if (selectedRow) {
            clearRowContents();
        }
    });

    // 3. Botón Borrar Fila
    btnDeleteRow.addEventListener('click', () => {
        if (selectedRow) {
            deleteRowContent();
        }
    });


    /** 
     * Maneja el guardado de contenido cuando el usuario termina de editar (focusout). 
     */
    cellGrid.addEventListener('focusout', function(e) {
        if (e.target.classList.contains('editable')) {
            const target = e.target;
            // El contenido que se guarda es lo que está visible en el DOM al perder foco.
            const newValue = target.textContent; 

            setCellValue(target, newValue);
        }
    });

    /** 
     * Maneja el guardado de contenido cuando se presiona Enter (keydown).
     */
    cellGrid.addEventListener('keydown', function(e) {
        if (e.target.classList.contains('editable')) {
            // Detectar la tecla Enter
            if (e.key === 'Enter') {
                e.preventDefault(); // Prevenir el comportamiento por defecto del formulario/cursor
                const target = e.target;
                const newValue = target.textContent; 

                setCellValue(target, newValue);
            }
        }
    });
}
```

